import PaperTile, { type PaperImage } from "./PaperTile";

const COLUMN_SIZES = "(min-width: 1152px) 340px, (min-width: 1024px) 30vw, (min-width: 640px) 45vw, 90vw";
const WIDE_SIZES = "(min-width: 1152px) 1000px, 90vw";

// Full class strings, so Tailwind can see every option.
const COLUMNS = {
  2: "columns-1 sm:columns-2",
  3: "columns-1 sm:columns-2 lg:columns-3",
  4: "columns-1 sm:columns-2 lg:columns-3 xl:columns-4",
} as const;

export interface TiltedCollageProps {
  images: PaperImage[];
  /** Most columns the wall breaks into on wide screens. */
  columns?: 2 | 3 | 4;
  /** Scales every tile's tilt and drop. 0 is a clean, straight masonry. */
  messiness?: number;
  className?: string;
}

// Columns of tiles at their own shape (nothing cropped), each mounted on white paper and set at a
// slight angle. A wide image breaks the columns and runs across the whole collage.
export function TiltedCollage({ images, columns = 3, messiness = 1, className }: TiltedCollageProps) {
  // Split the list into runs: each wide image on its own, and the images between them together.
  const runs: PaperImage[][] = [];
  for (const image of images) {
    const last = runs.at(-1);
    if (image.wide || !last || last[0].wide) runs.push([image]);
    else last.push(image);
  }

  return (
    <div className={`flex flex-col gap-10 sm:gap-14 ${className ?? ""}`}>
      {runs.map((run) =>
        run[0].wide ? (
          <div key={run[0].src} className="mx-auto w-full max-w-5xl px-2">
            <PaperTile image={run[0]} index={images.indexOf(run[0])} sizes={WIDE_SIZES} messiness={messiness} />
          </div>
        ) : (
          <ul key={run[0].src} className={`${COLUMNS[columns] ?? COLUMNS[3]} gap-8 px-2 sm:gap-10`}>
            {run.map((image) => (
              <li key={image.src} className="mb-8 break-inside-avoid sm:mb-10">
                <PaperTile image={image} index={images.indexOf(image)} sizes={COLUMN_SIZES} messiness={messiness} />
              </li>
            ))}
          </ul>
        ),
      )}
    </div>
  );
}

export default TiltedCollage;

import type { CSSProperties } from "react";

// `wide`: a long strip (e.g. a 5-frame storyboard), shown across the whole collage instead of in a column.
export type PaperImage = {
  src: string;
  width: number;
  height: number;
  alt: string;
  wide?: boolean;
};

// Each tile's tilt (deg) and drop from the tile above (px), cycled through in order. Fixed rather
// than random so the layout looks the same on every load and the server and client agree.
export const TILTS = [-2, 1.5, -1, 2.5, -1.5, 1, -2.5, 0.5];
const DROPS = [0, 14, 6, 20, 10, 2];

// The slow, soft ease every paper motion uses: quick start, long gentle settle.
export const EASE_SOFT = "ease-[cubic-bezier(0.22,1,0.36,1)]";

// White paper mount; on hover it straightens and lifts. Tilt comes from --tilt (halved on phones).
export const MOUNT = `relative bg-white p-2 shadow-[0_10px_30px_-12px_rgba(23,23,23,0.35)] ring-1 ring-black/5 transition duration-500 ${EASE_SOFT} rotate-[calc(var(--tilt)*0.5)] sm:p-3 sm:rotate-(--tilt) hover:z-10 hover:rotate-0 hover:scale-103 hover:shadow-[0_20px_40px_-14px_rgba(23,23,23,0.45)] motion-reduce:transition-none motion-reduce:hover:scale-100`;

export interface PaperTileProps {
  image: PaperImage;
  index: number;
  sizes: string;
  /** Scales both the tilt and the drop. 0 is a clean, straight tile. */
  messiness?: number;
  loading?: "eager" | "lazy";
}

// An image at its own shape (nothing cropped), mounted on white paper and set at a slight angle.
export default function PaperTile({ image, index, sizes, messiness = 1, loading = "lazy" }: PaperTileProps) {
  // Wide strips sit nearly level; a big tilt on a long tile swings its ends far out.
  const tilt = TILTS[index % TILTS.length] * (image.wide ? 0.3 : 1) * messiness;
  const style = {
    "--tilt": `${tilt}deg`,
    paddingTop: image.wide ? 0 : DROPS[index % DROPS.length] * messiness,
  } as CSSProperties;

  return (
    <div style={style}>
      <div className={MOUNT}>
        <img
          src={image.src}
          alt={image.alt}
          width={image.width}
          height={image.height}
          sizes={sizes}
          loading={loading}
          draggable={false}
          className="block h-auto w-full"
        />
      </div>
    </div>
  );
}

export { PaperTile };
